This Terraform configuration creates a complete AWS setup with:

- A custom VPC
- Public subnet
- Internet Gateway and route table
- Security group allowing HTTP access
- A `t2.micro` EC2 instance running a simple web server
- A Network Load Balancer
- Target group attached to the EC2 instance
- TCP listener on port `80`
- Outputs for the EC2 public IP and NLB DNS name

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

